'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n==null?'—':new Intl.NumberFormat('en-GB',{maximumFractionDigits:0}).format(n);
const names={overview:'Overview',players:'Player explorer',fodder:'Fodder watch',movers:'Market movers',watchlist:'My watchlist',alerts:'My price alerts',investments:'My investments',calculator:'Trade calculator',branding:'Brand & channels',publish:'Publish fodder',activity:'Activity log'};
let me,csrf='',guild='',market,alerts=[],watched=[],holdings=[],page='overview',selected=null,hours=24,rating='all',direction='risers',brand=null,channels=[],viewId=0,searchTimer,toastTimer;
async function api(path,options={}){const response=await fetch('/api/'+path,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.method&&options.method!=='GET'?{'X-CSRF-Token':csrf}:{}),...options.headers}});const data=await response.json();if(!response.ok){if(response.status===401&&me){me=null;$('#shell').hidden=true;$('#login').hidden=false;}throw new Error(data.error||'The request failed.');}return data;}
const post=(path,data={},method='POST')=>api(path,{method,body:JSON.stringify(data)});
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function heading(label,title,copy,action=''){return `<div class="page-heading"><div><span class="eyebrow">${label}</span><h1>${title}</h1><p>${copy}</p></div>${action}</div>`;}
function img(c,small=false){return c.image&&c.image.startsWith('https://')?`<img class="${small?'mini-image':'card-image'}" src="${esc(c.image)}" alt="${esc(c.name)} ${c.rating??''} card" loading="lazy">`:`<span class="card-fallback">${esc(c.rating??'?')}</span>`;}
function change(c){return c.change==null?'<span class="muted">No baseline</span>':`<span class="${c.change>=0?'positive':'negative'}">${c.change>=0?'↗ +':'↘ '}${c.change.toFixed(1)}%${Math.abs(c.change)>=50?'<small class="muted" style="display:block">Large move · verify</small>':''}</span>`;}
function empty(title,copy){return `<div class="empty"><b>${title}</b>${copy}</div>`;}
function table(cards,{actions=true,remove=false}={}){if(!cards.length)return empty('Nothing on the team sheet yet.','Search for a player to get started. Only fresh prices appear in market lists.');return `<div class="table-scroll"><table class="player-list"><thead><tr><th>PLAYER / ITEM</th><th>LOWEST BIN</th><th>~24H</th>${actions?'<th>YOUR MOVE</th>':''}</tr></thead><tbody>${cards.map(c=>`<tr><td><div class="player-name">${img(c,true)}<span><button data-card="${esc(c.id)}">${esc(c.name)}</button><small>${esc(c.rating??'—')} ${esc(c.position??'')} · ${esc(c.rarity??'')} ${c.stale?'· Price unavailable':''}</small></span></div></td><td><b>${fmt(c.value)}</b><small class="muted"> coins</small></td><td>${change(c)}</td>${actions?`<td><div class="row-actions"><button class="icon-button" data-alert="${esc(c.id)}" data-name="${esc(c.name)}" title="Set price target">🔔</button><button class="icon-button" ${remove?'data-unwatch':'data-watch'}="${esc(c.id)}" title="${remove?'Remove from':'Add to'} watchlist">${remove?'×':'☆'}</button></div></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function allCards(){const byId=new Map();for(const c of [...(market?.fodder??[]).flatMap(r=>r.cards),...(market?.risers??[]),...(market?.fallers??[]),...watched])byId.set(c.id,c);return [...byId.values()];}
async function personal(){const results=await Promise.allSettled([api('alerts'),api('watchlist'),api('investments')]);if(results[0].status==='fulfilled')alerts=results[0].value.alerts;if(results[1].status==='fulfilled')watched=results[1].value.cards;if(results[2].status==='fulfilled')holdings=results[2].value.holdings;for(const r of results)if(r.status==='rejected')toast(r.reason.message);$('#watch-count').textContent=watched.length;$('#alert-count').textContent=alerts.filter(a=>['active','paused','queued'].includes(a.state)).length;}
async function refresh(){const result=await Promise.allSettled([api('market'),personal()]);market=result[0].status==='fulfilled'?result[0].value:{fodder:[],risers:[],fallers:[],freshCards:null,error:result[0].reason.message};$('#market-status').textContent=market.error?'Market unavailable':market.freshCards?`${fmt(market.freshCards)} fresh cards`:'No fresh prices';$('#data-note').textContent=`FC${me.year} / ${me.platform.toUpperCase()} · Market lists cached up to 5 minutes. Observed BINs.`;}
async function render(){const version=++viewId;$$('nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#breadcrumb').textContent=names[page];$('#main').innerHTML='<div class="loading">LOADING YOUR CONTROL ROOM…</div>';$('.sidebar').classList.remove('open');try{let html='';
if(page==='overview'){
 const lowest=market.fodder.find(r=>r.rating===85)?.cards[0];html=heading('YOUR GAME / YOUR NUMBERS','THE NEXT MOVE.','Your personal targets, fresh market prices and the cards worth keeping an eye on.',`<button class="button primary" data-page="players">Find a player ↗</button>`)+`<div class="stats"><article class="stat"><span class="stat-label">FRESH MARKET CARDS</span><div class="big-number">${fmt(market.freshCards)}</div><small>Current configured market</small></article><article class="stat"><span class="stat-label">YOUR WATCHLIST</span><div class="big-number">${watched.length}<small> / 100</small></div><small>Private to your Discord account</small></article><article class="stat"><span class="stat-label">ACTIVE TARGETS</span><div class="big-number">${alerts.filter(a=>a.state==='active').length}<small> / ${me.alertLimit}</small></div><small>Waiting for your price</small></article><article class="stat"><span class="stat-label">CHEAPEST 85 RATED</span><div class="big-number">${fmt(lowest?.value)}</div><small>${esc(lowest?.name??'No fresh observation')}</small></article></div><div class="hero-strip"><div><span class="mono">THE FODDER FILE / LIVE MARKET</span><h2>BUILD SMART.<br>KEEP YOUR COINS.</h2><p>Compare the cheapest options at each rating before committing your club to the next SBC.</p><button class="button orange" data-page="fodder" style="margin-top:17px">Open fodder watch →</button></div><span class="giant">83<br>91</span></div><div class="grid-two"><section class="panel"><div class="panel-head"><h3>⭐ Your watchlist</h3><span class="mono">PERSONAL FILE</span></div>${table(watched.slice(0,5),{remove:true})}</section><section class="panel"><div class="panel-head"><h3>📉 Biggest drops</h3><span class="mono">~24H</span></div>${table(market.fallers.slice(0,4),{actions:false})}</section></div>`;
}
if(page==='fodder'){const rows=market.fodder.filter(r=>rating==='all'||r.rating===Number(rating));html=heading('THE RATING LADDER / SBC RESEARCH','FODDER WATCH.','Lowest fresh observed prices by exact rating. Compare alternatives, then check rarity and SBC requirements in-game.',`<a class="button" href="/api/fodder-image" download="futbot-fodder.png">Download board ↓</a>`)+`<div class="filterbar">${['all',83,84,85,86,87,88,89,90,91].map(r=>`<button data-rating="${r}" class="${rating===String(r)?'active':''}">${r==='all'?'ALL RATINGS':r}</button>`).join('')}</div><div class="rating-grid">${rows.map(r=>{const c=r.cards[0];return `<article class="rating-card"><div class="rating-top"><span class="rating-number">${r.rating}<small>RATED</small></span><span class="tag live">${c?'FRESH BIN':'NO DATA'}</span></div>${c?`<div class="cheapest">${img(c)}<div><b>${esc(c.name)}</b><small>${esc(c.rarity??'')} · ${esc(c.position??'')}</small><span class="price">${fmt(c.value)} <small>COINS</small></span>${change(c)}<div class="row-actions" style="margin-top:9px"><button class="icon-button" data-card="${c.id}">View card ↗</button><button class="icon-button" data-alert="${c.id}" data-name="${esc(c.name)}">🔔</button></div></div></div><div class="alternatives">${r.cards.slice(1).map(c=>`<div><span>${esc(c.name)}</span><b>${fmt(c.value)}</b></div>`).join('')||'No other fresh-priced cards at this rating.'}</div>`:empty('Waiting for prices.','No fresh cards at this rating.')}</article>`;}).join('')}</div><p class="note">These are the cheapest cards in the available catalogue, not an eligibility guarantee. Platform, rarity, league, tradeability and specific SBC rules still matter. Changes use a median of at least three observations 24–25 hours ago.</p>`;}
if(page==='movers')html=heading('THE MARKET / IN MOTION','WHO’S MOVING?','80+ rated cards priced at least 1,000 coins. Compared with the median of at least three observations 24–25 hours ago. Large moves still need checking in-game.')+`<div class="filterbar"><button data-direction="risers" class="${direction==='risers'?'active':''}">↗ RISERS</button><button data-direction="fallers" class="${direction==='fallers'?'active':''}">↘ FALLERS</button></div><section class="panel"><div class="panel-head"><h3>${direction==='risers'?'📈 The risers':'📉 The fallers'}</h3><span class="mono">TOP 10 / ${esc(me.platform.toUpperCase())}</span></div>${table(market[direction])}</section>`;
if(page==='watchlist')html=heading('YOUR PERSONAL FILE / PRIVATE','THE WATCHLIST.','Saved cards follow your account across Discord and this dashboard. Stale prices are withheld.',`<button class="button primary" data-page="players">Add a player +</button>`)+`<section class="panel"><div class="panel-head"><h3>⭐ Your saved players</h3><span class="mono">${watched.length} / 100</span></div>${table(watched,{remove:true})}</section>`;
if(page==='players'){html=heading('PLAYER FILES / EXACT CARD SEARCH','KNOW YOUR CARD.','Search the live catalogue for an exact item. Chart ranges use hourly medians; the headline shows the latest observed BIN.')+`<div class="search-wrap"><div class="searchbox"><span>⌕</span><input id="player-search" placeholder="Player name or card ID…" autocomplete="off" aria-label="Search players"><kbd>FC${me.year}</kbd></div><div id="search-results" hidden></div></div><div class="filterbar"><button data-mode="lookup" class="active">PLAYER LOOKUP</button><form id="budget-form" class="filterbar" style="margin:0"><input name="budget" type="number" min="1" max="15000000" required placeholder="Coin budget" aria-label="Coin budget" style="max-width:160px;padding:8px;border:1px solid var(--line)"><select name="position" aria-label="Position" style="padding:8px;border:1px solid var(--line)"><option value="">Any position</option>${['GK','CB','LB','RB','CDM','CM','CAM','LM','RM','LW','RW','ST'].map(p=>`<option>${p}</option>`).join('')}</select><button type="submit">FIND BUDGET CARDS →</button></form></div><div id="player-detail">${empty('The right version matters.','Type at least two characters, then choose the exact card from the results.')}</div>`;}
if(page==='alerts')html=heading('YOUR TARGETS / PRIVATE TO YOU','WAIT FOR YOUR PRICE.','Create buy or sell targets, pause them, and check their delivery state.',`<button class="button" id="testdm">Send test DM 🔔</button>`)+`<p class="note">${me.alertLimit} active, queued or paused alerts per account. A queued notification cannot be cancelled. Triggered targets are one-shot: create a new alert to watch again.</p><section class="panel"><div class="panel-head"><h3>🔔 Your saved alerts</h3><button class="button primary small" data-page="players">Create from a player +</button></div>${alerts.length?`<div class="table-scroll"><table class="player-list"><thead><tr><th>PLAYER / SAVED TARGET</th><th>CURRENT BIN</th><th>TO TARGET</th><th>STATE</th><th>CREATED</th><th>CONTROLS</th></tr></thead><tbody>${alerts.map(a=>`<tr><td><b>${esc(a.card_name)}</b><div class="muted" style="font-size:11px">#${a.id} · ${a.direction==='below'?'Buy at or below':'Sell at or above'} ${fmt(a.target)} coins · ${esc(a.platform.toUpperCase())}</div></td><td><b>${fmt(a.currentPrice)}</b><small class="muted">${a.currentPrice==null?'Unavailable':a.priceFresh?' coins':' coins · ⚠ Stale'}</small>${a.priceCapturedAt?`<div class="muted" style="font-size:11px">Updated ${esc(new Date(a.priceCapturedAt).toLocaleString('en-GB'))}</div>`:''}</td><td>${a.gap==null?'—':a.gap===0?'Target met':`${fmt(a.gap)} coins ${a.direction==='below'?'to drop':'to rise'}`}</td><td><span class="tag ${a.state==='active'?'live':a.state==='failed'?'orange':''}">${esc(a.state)}</span></td><td>${new Date(a.created_at).toLocaleDateString('en-GB')}</td><td><div class="row-actions">${['active','paused'].includes(a.state)?`<button class="icon-button" data-alert-state="${a.state==='active'?'paused':'active'}" data-id="${a.id}">${a.state==='active'?'⏸ Pause':'▶ Resume'}</button>`:''}${['active','paused','failed'].includes(a.state)?`<button class="icon-button" data-cancel="${a.id}">Cancel ×</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No targets yet.','Open a player and choose Buy alert or Sell alert.')}</section>`;
if(page==='calculator')html=heading('COIN DESK / 5% EA TAX','DO THE MATHS.','Calculate the trade before you buy. Values are estimates; break-even rounds up to a whole coin.')+`<div class="grid-even"><form class="panel form-panel" id="tax-form"><h3>🧮 Trade calculator</h3><label>Buy price per card<input name="buy" type="number" min="1" max="15000000" value="100000" required></label><label>Sell price per card<input name="sell" type="number" min="1" max="15000000" value="120000" required></label><label>Copies<input name="quantity" type="number" min="1" max="1000" value="1" required></label><button class="button primary full">Calculate →</button></form><div id="tax-result"></div></div>`;
if(page==='investments')html=heading('YOUR COIN BOOK / PRIVATE','TRACK YOUR POSITION.','Record what you bought. Valuations use fresh observed BINs and subtract 5% EA tax; this does not connect to your EA club.')+`<div class="holdings-total"><span class="eyebrow">UNREALISED PROFIT / FRESH-PRICED HOLDINGS ONLY</span><div class="big-number">${fmt(holdings.filter(h=>h.fresh).reduce((n,h)=>n+h.profit,0))} <small>COINS</small></div><span class="mono">${holdings.filter(h=>h.fresh).length} / ${holdings.length} POSITIONS VALUED</span></div><div class="grid-two"><section class="panel"><div class="panel-head"><h3>▦ Your holdings</h3><span class="mono">AFTER TAX</span></div>${holdings.length?`<div class="table-scroll"><table class="player-list"><thead><tr><th>ITEM / COPIES</th><th>BUY / EACH</th><th>PROFIT</th><th></th></tr></thead><tbody>${holdings.map(h=>`<tr><td><b>${esc(h.card_name)}</b><div class="muted">${h.quantity} copies · ${h.fresh?'Fresh price':'Price unavailable / stale'}</div></td><td>${fmt(h.buy_price)}</td><td class="${h.profit>=0?'positive':'negative'}">${h.fresh?fmt(h.profit):'—'}</td><td><button class="icon-button" data-delete-holding="${h.id}" title="Delete this record">×</button></td></tr>`).join('')}</tbody></table></div>`:empty('Start your coin book.','Add a card ID, entry price and number of copies.')}</section><form id="holding-form" class="panel form-panel"><h3>Record a purchase</h3><p class="hint">Find the exact card ID in Player explorer first.</p><label>Card ID<input name="cardId" pattern="[0-9]+" required placeholder="Exact card ID"></label><label>Buy price per card<input name="buy" type="number" min="1" max="15000000" required></label><label>Copies<input name="quantity" type="number" min="1" max="1000" value="1" required></label><button class="button primary full">Add position +</button></form></div>`;
if(['branding','publish','activity'].includes(page)){
 if(!guild){html=empty('Choose a server workspace.','Only servers where you can Manage Server and FutBot is installed appear in the selector.');}
 else if(page==='branding'){
 [brand,channels]=await Promise.all([api(`guilds/${guild}/settings`),api(`guilds/${guild}/channels`).then(r=>r.channels)]);html=heading('SERVER CONTROL / YOUR IDENTITY','MAKE IT YOURS.','These settings are saved to your server and used by live Discord results. Your bot’s Discord username and avatar remain managed in the Developer Portal.')+`<div class="grid-even"><form class="panel form-panel" id="brand-form"><h3>◈ Server identity</h3><label>Embed author name<input name="name" maxlength="50" value="${esc(brand.name)}" required></label><div class="form-grid"><label>Accent colour<input name="accent" type="color" value="${esc(brand.accent)}"></label><label>Fodder publishing channel<select name="channel"><option value="">Choose a channel</option>${channels.map(c=>`<option value="${c.id}" ${c.id===brand.settings.fodderChannel?'selected':''}>#${esc(c.name)}</option>`).join('')}</select></label></div><label>Embed footer<input name="footer" maxlength="120" value="${esc(brand.footer)}"></label><p class="hint">Channel choices require View Channel, Send Messages and Embed Links. Publishing images also requires Attach Files.</p><button class="button primary full">Save server settings →</button></form><section class="preview-shell"><div class="discord-meta"><span class="bot-icon">F</span><b id="preview-name">${esc(brand.name)}</b><span class="app-tag">APP</span><small class="muted">preview</small></div><div class="discord-embed" id="embed-preview" style="border-color:${esc(brand.accent)}"><h3>🧱 FODDER WATCH</h3><p>Fresh market prices. Your community’s own presentation.</p><div class="discord-fields"><span><b>83 RATED</b>Live market price</span><span><b>85 RATED</b>Live market price</span><span><b>88 RATED</b>Live market price</span></div><img src="/api/fodder-image" alt="Live fodder board preview"><footer id="preview-footer">${esc(brand.footer)}</footer></div></section></div>`;
 }else if(page==='publish'){brand=await api(`guilds/${guild}/settings`);html=heading('SERVER CONTROL / YOUR FODDER DESK','READY FOR THE FEED.','Preview the current board and send it to your configured server channel. Each click publishes one message; no recurring posting is enabled.')+`<div class="grid-two"><section class="panel"><div class="panel-head"><h3>🧱 Live fodder board</h3><span class="tag live">CURRENT SNAPSHOT</span></div><img class="feed-preview" src="/api/fodder-image" alt="Current fodder price ladder"></section><section class="panel form-panel"><span class="eyebrow">YOUR SERVER / YOUR CONTENT</span><h2>${esc(brand.name)}</h2><p class="hint">Channel: ${brand.settings.fodderChannel?'Saved in server settings':'Not configured yet'}</p><div class="publish-note">This posts a real message to your Discord server. Confirm the preview and channel before publishing. Members will see your server’s name, accent and footer.</div><button class="button primary full" id="publish-fodder" ${brand.settings.fodderChannel?'':'disabled'}>Publish to Discord ↗</button><button class="button full" data-page="branding">Change channel & branding</button><div id="publish-result"></div></section></div>`;
 }else{const data=await api(`guilds/${guild}/activity`);html=heading('SERVER CONTROL / THE PAPER TRAIL','ACTIVITY LOG.','Real server setting changes and published fodder boards. Personal targets and investments never appear here.')+`<section class="panel"><div class="panel-head"><h3>≡ Recent actions</h3><span class="mono">LAST 30 EVENTS</span></div>${data.activity.length?data.activity.map(a=>`<div class="audit-row"><span class="audit-icon">${a.action==='fodder.published'?'▣':'◈'}</span><div><b>${a.action==='fodder.published'?'Fodder board published':'Server settings updated'}</b><small>${esc(a.details.name??a.details.channel??'Server configuration')}</small></div><time>${new Date(a.created_at).toLocaleString('en-GB')}</time></div>`).join(''):empty('A clean team sheet.','Saved settings and publications will appear here.')}</section>`;}
}
if(version!==viewId)return;if(market?.error&&['overview','fodder','movers'].includes(page))html=`<div class="error" style="margin-bottom:20px"><h3>Market data unavailable</h3><p>${esc(market.error)}</p><span>Player lookup, alerts, calculator and server settings can still be used. Press refresh to retry the market.</span></div>`+html;$('#main').innerHTML=html;bindPage();if(page==='players'&&selected)await showCard(selected,hours);if(page==='calculator')calculate();
}catch(e){if(version===viewId)$('#main').innerHTML=`<div class="error"><h2>Couldn’t load this page.</h2><p>${esc(e.message)}</p><button class="button" data-retry>Try again ↻</button></div>`;}}
function openAlert(id,name,side='below'){const f=$('#alert-form');f.elements.cardId.value=id;f.elements.direction.value=side;f.elements.target.value='';$('#alert-player').textContent=name;$('#alert-dialog').showModal();}
async function showCard(id,range=24){selected=id;hours=range;const target=$('#player-detail');if(!target)return;target.innerHTML='<div class="loading">LOADING THE PLAYER FILE…</div>';try{const data=await api(`card?id=${id}&hours=${range}`);if(selected!==id||hours!==range||!$('#player-detail'))return;const {card:c,price:p,history}=data;const low=history.length?Math.min(...history.map(p=>p.value)):null,high=history.length?Math.max(...history.map(p=>p.value)):null;$('#player-detail').innerHTML=`<section class="panel"><div class="detail-hero">${img(c)}<div><span class="eyebrow">PLAYER FILE #${c.id} / ${esc(me.platform.toUpperCase())}</span><h2>${esc(c.name)}</h2><p class="muted">${c.rating??'—'} ${esc(c.position??'')} · ${esc(c.rarity??'')} · ${esc(c.club??'')}</p><div class="detail-price">${fmt(p?.value)} <small style="font-size:16px">COINS</small></div><span class="tag ${data.fresh?'live':'orange'}">${data.fresh?'FRESH OBSERVATION':'STALE / UNAVAILABLE'}</span><small class="muted"> ${p?new Date(p.capturedAt).toLocaleString('en-GB'):''}</small><div class="detail-actions"><button class="button primary small" data-alert="${c.id}" data-name="${esc(c.name)}">🔔 Buy alert</button><button class="button small" data-alert="${c.id}" data-name="${esc(c.name)}" data-side="above">📈 Sell alert</button><button class="button small" data-watch="${c.id}">☆ Watch</button></div></div></div><div class="chart-box"><div class="filterbar"><button data-range="24" class="${range===24?'active':''}">24 HOURS</button><button data-range="168" class="${range===168?'active':''}">7 DAYS</button>${history.length>=2?`<a class="text-link spacer" href="/api/chart?id=${c.id}&hours=${range}" download="futbot-${c.id}.png">Download chart ↓</a>`:''}</div>${history.length>=2?`<img class="chart-image" src="/api/chart?id=${c.id}&hours=${range}" alt="${esc(c.name)} hourly median price chart">`:empty('More observations needed.','The chart appears once two different observation times are available.')}<div class="chart-summary"><span>PERIOD LOW<b>${fmt(low)}</b></span><span>PERIOD HIGH<b>${fmt(high)}</b></span><span>AFTER TAX<b>${p?fmt(Math.floor(p.value*.95)):'—'}</b></span></div><p class="hint">High/low values and the chart use hourly medians within the selected period. The headline uses the latest observation. Prices are not guaranteed listings.</p></div></section>`;}catch(e){target.innerHTML=`<div class="error">${esc(e.message)}</div>`;}}
function calculate(){const form=$('#tax-form');if(!form||!form.checkValidity())return;const buy=Number(form.elements.buy.value),sell=Number(form.elements.sell.value),qty=Number(form.elements.quantity.value),net=Math.floor(sell*.95),profit=(net-buy)*qty;$('#tax-result').innerHTML=`<section class="holdings-total"><span class="eyebrow">PROFIT AFTER EA TAX</span><div class="big-number">${profit>=0?'+':''}${fmt(profit)} <small>COINS</small></div><span class="mono">${qty} COP${qty===1?'Y':'IES'} / ${fmt(profit/qty)} EACH</span></section><div class="stats" style="grid-template-columns:1fr 1fr"><article class="stat"><span class="stat-label">TOTAL EA TAX</span><div class="big-number">${fmt((sell-net)*qty)}</div></article><article class="stat"><span class="stat-label">BREAK-EVEN / COPY</span><div class="big-number">${fmt(Math.ceil(buy/.95))}</div></article></div><p class="note">The transfer market only accepts valid price increments. Choose the next valid listing price at or above this mathematical break-even.</p>`;}
function bindPage(){const search=$('#player-search');if(search){let seq=0;search.oninput=()=>{clearTimeout(searchTimer);const q=search.value.trim(),n=++seq;if(q.length<2){$('#search-results').hidden=true;return;}searchTimer=setTimeout(async()=>{try{const data=await api('search?q='+encodeURIComponent(q));if(n!==seq||!$('#search-results'))return;$('#search-results').hidden=false;$('#search-results').innerHTML=data.cards.length?data.cards.map(c=>`<button class="search-result" data-card="${c.id}">${img(c,true)}<span><b>${esc(c.name)}</b><small>${c.rating??'—'} ${esc(c.position??'')} · ${esc(c.rarity??'')} · #${c.id}</small></span></button>`).join(''):empty('No matching cards.','Try a shorter name or exact ID.');}catch(e){toast(e.message);}},300);};}
const tax=$('#tax-form');if(tax){tax.onsubmit=e=>{e.preventDefault();calculate();};tax.oninput=calculate;}
const budget=$('#budget-form');if(budget)budget.onsubmit=async e=>{e.preventDefault();await busy(budget.querySelector('button'),async()=>{const b=Number(budget.elements.budget.value),position=budget.elements.position.value,data=await api(`budget?coins=${b}&position=${encodeURIComponent(position)}`);$('#player-detail').innerHTML=`<section class="panel"><div class="panel-head"><h3>💎 Under ${fmt(b)} coins</h3><span class="mono">PRIMARY POSITION</span></div>${table(data.cards)}</section>`;});};
const form=$('#brand-form');if(form){form.oninput=()=>{$('#preview-name').textContent=form.elements.name.value;$('#preview-footer').textContent=form.elements.footer.value;$('#embed-preview').style.borderColor=form.elements.accent.value;};form.onsubmit=async e=>{e.preventDefault();await busy(form.querySelector('button'),async()=>{await post(`guilds/${guild}/settings`,{name:form.elements.name.value,accent:form.elements.accent.value,footer:form.elements.footer.value,settings:{fodderChannel:form.elements.channel.value}},'PUT');toast('Server settings saved. New Discord results will use your branding.');});};}
const hf=$('#holding-form');if(hf)hf.onsubmit=async e=>{e.preventDefault();await busy(hf.querySelector('button'),async()=>{await post('investments',{cardId:hf.elements.cardId.value,buy:Number(hf.elements.buy.value),quantity:Number(hf.elements.quantity.value)});await personal();await render();toast('Purchase recorded.');});};}
async function busy(button,fn){if(button?.disabled)return;const original=button?.textContent;if(button){button.disabled=true;button.textContent='Working…';}try{await fn();}catch(e){toast(e.message);}finally{if(button?.isConnected){button.disabled=false;button.textContent=original;}}}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;
if(b.dataset.page){page=b.dataset.page;await render();return;}if(b.hasAttribute('data-retry')){await render();return;}
if(b.dataset.card){if($('#search-results'))$('#search-results').hidden=true;const id=b.dataset.card;selected=id;if(page!=='players'){page='players';await render();}else await showCard(id,hours);return;}
if(b.dataset.alert){openAlert(b.dataset.alert,b.dataset.name,b.dataset.side);return;}
if(b.dataset.watch){await busy(b,async()=>{await post('watchlist',{id:b.dataset.watch});await personal();toast('⭐ Added to your private watchlist.');});return;}
if(b.dataset.unwatch){await busy(b,async()=>{await post('watchlist',{id:b.dataset.unwatch},'DELETE');await personal();await render();toast('Removed from watchlist.');});return;}
if(b.dataset.rating){rating=b.dataset.rating;await render();return;}if(b.dataset.direction){direction=b.dataset.direction;await render();return;}if(b.dataset.range){await showCard(selected,Number(b.dataset.range));return;}
if(b.dataset.alertState){await busy(b,async()=>{await post('alerts',{id:b.dataset.id,state:b.dataset.alertState},'PATCH');await personal();await render();});return;}
if(b.dataset.cancel){await busy(b,async()=>{await post('alerts',{id:b.dataset.cancel},'DELETE');await personal();await render();toast('Alert cancelled.');});return;}
if(b.dataset.deleteHolding){await busy(b,async()=>{await post('investments',{id:b.dataset.deleteHolding},'DELETE');await personal();await render();toast('Record removed.');});return;}
if(b.hasAttribute('data-close')){$('#alert-dialog').close();return;}
if(b.id==='testdm'){await busy(b,async()=>{await post('testdm');toast('Test sent. Check your Discord DMs.');});return;}
if(b.id==='publish-fodder'){await busy(b,async()=>{const data=await post(`guilds/${guild}/publish`);$('#publish-result').innerHTML=`<p class="note">Published. <a href="${esc(data.url)}" target="_blank" rel="noopener">View in Discord ↗</a></p>`;toast('Fodder board published to Discord.');});return;}
});
$('#alert-form').onsubmit=async e=>{e.preventDefault();const f=e.target;await busy(f.querySelector('[type=submit]'),async()=>{await post('alerts',{cardId:f.elements.cardId.value,target:Number(f.elements.target.value),direction:f.elements.direction.value});$('#alert-dialog').close();await personal();if(page==='alerts')await render();toast('🔔 Your price alert is now watching.');});};
$('#guild').onchange=async()=>{guild=$('#guild').value;$('#admin-nav').hidden=!guild;$('#workspace-title').textContent=$('#guild').selectedOptions[0].textContent;if(['branding','publish','activity'].includes(page)&&!guild)page='overview';await render();};
$('#mobile-menu').onclick=()=>$('.sidebar').classList.toggle('open');$('#refresh').onclick=()=>busy($('#refresh'),async()=>{await refresh();await render();toast('Data refreshed. Market cache lasts up to five minutes.');});$('#logout').onclick=()=>busy($('#logout'),async()=>{await post('logout');location.assign('/app/');});
async function boot(){try{me=await api('me');csrf=me.csrf;$('#login').hidden=true;$('#shell').hidden=false;$('#username').textContent=me.user.name;if(me.user.avatar){$('#avatar').src=me.user.avatar;$('#avatar').hidden=false;}await refresh();await render();try{const data=await api('guilds');$('#guild').querySelectorAll('option:not(:first-child)').forEach(o=>o.remove());for(const g of data.guilds){const o=document.createElement('option');o.value=g.id;o.textContent=g.name;$('#guild').append(o);}}catch(e){toast('Server list: '+e.message);}}catch(e){if(me){$('#shell').hidden=false;$('#login').hidden=true;$('#main').innerHTML=`<div class="error"><h2>Data is temporarily unavailable.</h2><p>${esc(e.message)}</p><button class="button" id="boot-retry">Reconnect ↻</button></div>`;$('#boot-retry').onclick=boot;}else{$('#login').hidden=false;$('#shell').hidden=true;}}}
boot();
